/*==========================================================================*/
/*                             I N C L U D E S                              */
/*==========================================================================*/
#include "rftd2_private.h"
#include "d2d.h"
#include "prog.h"
#include "bitfield.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/
static Boolean alert_sent = FALSE ; 
/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
void rftd2_dtc_alert_on (void * arg)
{	
	rf_icon_set (ICON_DTC, FALSE);	
}

//--------------------------------------------------------------------------//

void rftd2_dtc_alert_off (void * arg)
{	
    rf_icon_clr (ICON_DTC, FALSE);
	alert_sent = FALSE ;		
}

//--------------------------------------------------------------------------//

void rftd2_dtc_alert_update (void * arg)
{
	if(bitfield_rd(rf_data.icon.bit, ICON_DTC, ICON_DTC) && !alert_sent)
	{
		alert_sent = TRUE ;

		if (prog_retrieve_option (FEAT_RF_OUTPUT) == RF_TD2)
		{
		 	d2d_tx (AL_NEW_DTC_CODE);	
		}
	}
}
//--------------------------------------------------------------------------//
void rftd2_dtc_alert_update_ign_on (void * arg)
{
  rf_icon_set (ICON_IGNITION, FALSE);
  
  rftd2_dtc_alert_update(arg) ;
}
//--------------------------------------------------------------------------//
void rftd2_dtc_alert_update_ign_off (void * arg)
{
  rf_icon_clr (ICON_IGNITION, FALSE);
  
  rftd2_dtc_alert_update(arg) ;
}
